/** 보기 타입 저장 키 */
const VIEW_MODE_STORAGE_KEY = "mua-mail-view-mode";

interface MailLayoutProps {
    /**
     * 모바일 서브페이지(mfd 풀스크린 슬라이드) 안에 폴더 고정으로 마운트될 때의 설정.
     * 다이얼로그 본문에는 라우트 파라미터가 없으므로 폴더·계정을 props 로 받는다(MailSubPages).
     * 없으면 라우트(`mail` / `mail/account/:accountSeq` / `mail/:folder`)가 폴더를 정한다.
     */
    embedded?: {
        folder: MailListFolder; // 고정 폴더
        accountSeq?: number; // 받은편지함일 때 계정별(0/생략 = 전체 계정)
        folderSeq?: number; // 사용자 메일함(folder=custom)일 때 메일함 seq
        /**
         * 페이지 모드 — 폴더는 고정하되 서브페이지 다이얼로그 안이 아니라 라우트 페이지(모바일 하단 탭)로 그린다.
         * 다이얼로그 제목 브리지(건수/제목)를 쓰지 않고, 카드 목록 래퍼도 페이지 여백을 갖는다(inDialog=false).
         */
        inline?: boolean;
    };
}

/**
 * 메일 레이아웃 컴포넌트 — 폴더는 라우트(또는 embedded props)가 정한다(사이드바 메뉴와 1:1).
 *   `mail` = 받은편지함(전체 계정) · `mail/account/:accountSeq` = 계정별 받은편지함 · `mail/:folder` = 그 외 폴더(계정 선택 유지)
 * 데스크탑 = ListLayout 표 + 오른쪽 상세 패널, 모바일 = 카드 목록(MobileCardListLayout) + 상세/작성/계정 mfd 슬라이드.
 */
export default function MailLayout({ embedded }: MailLayoutProps = {}) {
    const controller = useMailController();
    const params = useParams<{ folder?: string; accountSeq?: string; folderSeq?: string }>();
    // ⚠️ 아래 effect 의존성은 embedded 객체가 아니라 원시값으로 둔다 — 호출부(MailSubPages)가 렌더마다 새 객체를
    //    만들고, 서브페이지 제목/건수 스토어 갱신이 호스트를 다시 그리므로 객체 의존성이면 무한 갱신 루프가 된다.
    const isEmbedded = Boolean(embedded);
    // 페이지 모드(하단 탭) — 다이얼로그 전용 처리(제목 브리지·inDialog)는 끈다.
    const isInline = Boolean(embedded?.inline);
    const embeddedFolder = embedded?.folder;
    const embeddedAccountSeq = embedded?.accountSeq ?? 0;
    // 사용자 메일함(`mail/folder/:folderSeq` 또는 embedded custom)
    const routeUserFolderSeq = isEmbedded
        ? embeddedFolder === "custom"
            ? (embedded?.folderSeq ?? 0)
            : 0
        : params.folderSeq !== undefined
          ? Number(params.folderSeq) || 0
          : 0;
    const routeFolder: MailListFolder =
        routeUserFolderSeq > 0 ? "custom" : (embeddedFolder ?? toRouteFolder(params.folder));
    // 계정별 받은편지함의 계정 seq(-1 = 계정을 지정하지 않음 → 현재 선택 유지).
    //  - embedded 받은편지함: 지정 계정(0 = 전체) · embedded 다른 폴더: 유지 · 라우트: `mail/account/:accountSeq` 만 지정
    const routeAccountSeq = isEmbedded
        ? embeddedFolder === "inbox"
            ? embeddedAccountSeq
            : -1
        : params.accountSeq !== undefined
          ? Number(params.accountSeq) || 0
          : -1;
    const isInboxRoute = isEmbedded
        ? embeddedFolder === "inbox"
        : params.folder === undefined && routeUserFolderSeq === 0;
    const { state } = controller;
    const isMobile = useIsMobile();
    // 모바일: 서브페이지 제목바 돋보기 ↔ 검색/필터 오버레이(코드샵 목록 화면과 동일).
    const searchOverlay = useMobileSearchOverlay();
    const searchOverlayOpen = searchOverlay.useValue("open") as boolean;
    useEffect(() => {
        if (!isMobile) {
            return;
        }
        searchOverlay.setValue("active", true);
        return () => {
            searchOverlay.setValue("active", false);
            searchOverlay.setValue("open", false);
        };
    }, [isMobile, searchOverlay]);
    const logined = useMuaLogined();
    // 모바일 셸(카드 목록 래퍼·상세 다이얼로그)은 앱이 주입하면 그것을, 없으면 패키지 기본을 쓴다.
    const { mobile: mobileConfig, appHostsMailManage } = useMuaConfig();
    const MobileCardListLayout = mobileConfig?.CardListLayout ?? DefaultMobileCardListLayout;
    const MobileDetailDialog = mobileConfig?.DetailDialog ?? DefaultMobileDetailDialog;

    // 서버 목록은 관리 다이얼로그용으로 **내 모든 팀** 공용을 담는다(in_sidebar=보기 범위 여부, 2026-09-03).
    // 셸(계정 필터·작성·이동 등)은 보기 범위 것만 쓴다 — 범위 밖 계정의 메일은 서버가 어차피 안 준다.
    const allAccounts = state.useValue("accounts") as MailAccount[];
    const accounts = useMemo(() => allAccounts.filter((a) => a.in_sidebar !== false), [allAccounts]);
    const messages = state.useValue("messages") as MailMessageListItem[];
    const total = state.useValue("total") as number;
    const loadingList = state.useValue("loadingList") as boolean;
    const filters = state.useValue("filters") as MailFilters;
    const selectedSeq = state.useValue("selectedSeq") as number;
    const detail = state.useValue("detail") as MailMessageDetail | null;
    const loadingDetail = state.useValue("loadingDetail") as boolean;
    const syncingSeqs = state.useValue("syncingSeqs") as number[];
    const syncing = syncingSeqs.length > 0;
    const error = state.useValue("error") as string;
    const counts = state.useValue("counts") as MailFolderCounts;

    // 서브페이지 제목바 — 건수 "(N)" 와, 계정별 받은편지함이면 폴더명 대신 계정 이름을 올린다.
    useEffect(() => {
        if (!isEmbedded || isInline) return;
        getMuaSubPageBridge()?.setCount?.(total);
        return () => getMuaSubPageBridge()?.setCount?.(null);
    }, [isEmbedded, isInline, total]);
    const allFolders = state.useValue("folders") as MailUserFolder[];
    const folders = useMemo(() => allFolders.filter((f) => f.in_sidebar !== false), [allFolders]);
    const currentUserFolder = useMemo(
        () => (filters.folder === "custom" ? folders.find((f) => f.seq === filters.mailFolderSeq) : undefined),
        [filters.folder, filters.mailFolderSeq, folders]
    );
    const embeddedAccountLabel = useMemo(() => {
        if (!isEmbedded) return null;
        if (routeUserFolderSeq > 0) return currentUserFolder?.name ?? "메일함";
        if (routeAccountSeq <= 0) return null;
        const account = accounts.find((a) => a.seq === routeAccountSeq);
        return account ? account.name || account.email : null;
    }, [isEmbedded, routeAccountSeq, routeUserFolderSeq, currentUserFolder, accounts]);
    useEffect(() => {
        if (!isEmbedded || isInline) return;
        getMuaSubPageBridge()?.setTitle?.(embeddedAccountLabel);
        return () => getMuaSubPageBridge()?.setTitle?.(null);
    }, [isEmbedded, isInline, embeddedAccountLabel]);

    /** 계정·건수를 다시 읽는다(계정 저장/삭제/동기화 후). */
    const refreshAccounts = useCallback(() => {
        void state.actions.loadAccounts().then(() => state.actions.loadCounts());
    }, [state.actions]);

    /** 목록·건수를 다시 읽는다(발송/임시저장 후). */
    const refreshList = useCallback(() => {
        void state.actions.loadMessages({ silent: true });
        void state.actions.loadCounts();
    }, [state.actions]);
    // 당겨서-새로고침(모바일 서브페이지 다이얼로그가 requestMailRefresh 로 부른다) — 목록·건수를 다시 읽고 끝날 때까지 기다린다.
    useEffect(
        () =>
            subscribeMailRefresh(async () => {
                await Promise.all([state.actions.loadMessages({ silent: true }), state.actions.loadCounts()]);
            }),
        [state.actions]
    );

    // 계정 폼·관리 다이얼로그·규칙 폼은 MailManageHost 가 그린다 — 여기서는 요청(manageRequest)만 보낸다.
    const compose = useComposeController({ onSent: refreshList, onDraftSaved: refreshList });

    // 최초 1회: 계정·메일함·규칙은 진입 부트스트랩 1건(takeMailEntry)에서 받고 건수만 따로 읽는다.
    // 메일 경로 새로고침이면 이 화면(자식)의 effect 가 셸 사이드바 훅보다 먼저 돌아 여기가 먼저 찜하고,
    // 사이드바 훅이 먼저 돌았으면 null 이 와서 그쪽이 채우는 것을 기다린다(요청은 어느 쪽이든 1건).
    // 이미 사이드바가 채워 둔 뒤(메일 화면 재진입)면 그대로 이어받아 건수만 읽는다 — 셸이 realtime·팀 전환을
    // 따라가므로 다시 읽을 이유가 없다(0.3.79). 규칙은 메일 화면만 쓰므로 못 받으면 개별 라우트로 읽는다.
    const initialLoadRef = useRef(false);
    useEffect(() => {
        if (initialLoadRef.current) return;
        initialLoadRef.current = true;
        const accountEntry = isMailSidebarFilled("accounts") ? null : takeMailEntry("accounts");
        if (accountEntry) {
            void accountEntry.then((rows) => {
                // 줄 것이 없으면(요청 실패·재진입) 계정부터 개별 라우트로 읽는다 — refreshAccounts 가 건수까지 본다.
                if (!rows) return refreshAccounts();
                state.setValue("accounts", rows);
                markMailSidebarFilled("accounts", true);
                void state.actions.loadCounts();
            });
        } else {
            void state.actions.loadCounts();
        }
        const folderEntry = isMailSidebarFilled("folders") ? null : takeMailEntry("folders");
        if (folderEntry) {
            void folderEntry.then((rows) => {
                if (!rows) return void state.actions.loadFolders();
                state.setValue("folders", rows);
                markMailSidebarFilled("folders", true);
            });
        }
        const ruleEntry = takeMailEntry("rules");
        if (ruleEntry) {
            void ruleEntry.then((rows) => (rows ? state.setValue("rules", rows) : void state.actions.loadRules()));
        }
    }, [refreshAccounts, state, state.actions]);

    // 라우트 → 필터(사이드바 메뉴 클릭/직접 진입). 필터 변화가 아래 effect 로 목록을 다시 읽는다.
    //  - 계정별 받은편지함: 폴더=받은편지함 + 그 계정
    //  - 받은편지함(전체): 폴더=받은편지함 + 전체 계정
    //  - 그 외 폴더: 폴더만 바꾸고 계정 선택은 유지(계정별 받은편지함에서 고른 계정이 다른 폴더에도 이어진다)
    useEffect(() => {
        if (routeAccountSeq >= 0) {
            state.actions.setFilters({ folder: "inbox", mailAccountSeq: routeAccountSeq });
        } else if (isInboxRoute) {
            state.actions.setFilters({ folder: "inbox", mailAccountSeq: 0 });
        } else if (routeUserFolderSeq > 0) {
            state.actions.setFilters({ folder: "custom", mailFolderSeq: routeUserFolderSeq });
        } else {
            state.actions.setFilters({ folder: routeFolder, mailFolderSeq: 0 });
        }
    }, [routeFolder, routeAccountSeq, routeUserFolderSeq, isInboxRoute, state.actions]);

    // 필터가 바뀌면 목록·건수 재조회
    const filterKey = `${filters.mailAccountSeq}|${filters.folder}|${filters.search}|${filters.unreadOnly}|${filters.starredOnly}`;
    useEffect(() => {
        void state.actions.loadMessages();
        void state.actions.loadCounts();
        // filterKey 로만 트리거한다.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [filterKey]);

    // realtime — 새 메일/발송 변동 시 해당 폴더를 보고 있으면 조용히 갱신
    const handleRealtime = useCallback(
        (data: MailChangedData) => {
            const current = state.getValue("filters") as MailFilters;
            const sameAccount =
                current.mailAccountSeq === 0 || current.mailAccountSeq === Number(data.mail_account_seq ?? 0);
            if (sameAccount && (data.folder ?? "inbox") === current.folder) {
                void state.actions.loadMessages({ silent: true });
            }
            void state.actions.loadCounts();
        },
        [state]
    );
    useMailRealtime({ enabled: logined, onEvent: handleRealtime });

    // 마지막에 고른 보내는 계정(mail_preference.last_account_seq) — 아래 설정 로딩 이펙트가 채운다.
    // 전역 상태에 둔다: 새 메일 창을 그리는 곳이 이 화면이 아니라 MailManageHost 라 둘이 같은 값을 봐야 한다.
    const lastAccountSeq = state.useValue("lastAccountSeq") as number;
    /**
     * 새 메일의 보내는 계정 — 마지막에 고른 계정 > 현재 보고 있는 계정 > 기본 발신 개인 계정 > 첫 계정.
     * "마지막에 고른 것" 을 앞에 두는 이유: 받은편지함을 이리저리 보다가 메일을 쓰는 경우가 많은데,
     * 그때 보고 있던 계정으로 발신자가 바뀌면 매번 다시 고르게 된다(2026-09-06).
     * 그 기억은 계정에 저장돼(mail_preference.last_account_seq) 다른 기기에서도 같다.
     */
    const defaultAccount = useMemo(
        () =>
            accounts.find((a) => a.seq === lastAccountSeq) ??
            accounts.find((a) => a.seq === filters.mailAccountSeq) ??
            accounts.find((a) => a.is_default) ??
            accounts[0],
        [accounts, filters.mailAccountSeq, lastAccountSeq]
    );
    /** 상세 메시지의 계정 */
    const detailAccount = useMemo(
        () => accounts.find((a) => a.seq === detail?.mail_account_seq) ?? defaultAccount,
        [accounts, detail, defaultAccount]
    );

    const handleCompose = useCallback(() => {
        if (!defaultAccount) {
            requestMailAccountForm(null); // 계정이 없으면 등록부터
            return;
        }
        compose.form.actions.openNew(defaultAccount);
    }, [defaultAccount, compose.form.actions]);

    /** 상세의 주소 클릭 → 그 주소를 받는 사람으로 새 메일(발신 계정 = 상세 메시지의 계정). */
    const handleComposeTo = useCallback(
        (address: string) => {
            if (!detailAccount) {
                requestMailAccountForm(null);
                return;
            }
            compose.form.actions.openNew(detailAccount, address);
        },
        [detailAccount, compose.form.actions]
    );

    // 주소록에 있는 메일 주소 집합 — 상세의 "주소록 추가" 아이콘은 없는 주소에만 보인다(추가하면 즉시 사라진다).
    const [contactEmails, setContactEmails] = useState<Set<string>>(() => new Set());
    useEffect(() => {
        if (!logined) return;
        let cancelled = false;
        void mailApi
            .listContacts("")
            .then((res) => {
                if (cancelled || !res || res.ok === false) return;
                setContactEmails(new Set((res.data?.items ?? []).map((c) => c.email.toLowerCase())));
            })
            .catch(() => undefined);
        return () => {
            cancelled = true;
        };
    }, [logined]);
    const detailFromAddress = String(detail?.from?.address ?? "").toLowerCase();
    const canAddContact = Boolean(detailFromAddress) && !contactEmails.has(detailFromAddress);
    // 주소록에 있는 보낸 사람의 메일은 외부 이미지를 차단하지 않는다(신뢰 발신자).
    const trustedSender = Boolean(detailFromAddress) && contactEmails.has(detailFromAddress);

    /** 상세의 보낸 사람 → 주소록 추가(같은 주소가 이미 있으면 안내만 하고 아이콘을 감춘다). */
    const handleAddContact = useCallback(
        async (address: string, name: string) => {
            const key = address.toLowerCase();
            try {
                // 공용 메일 계정으로 받은 메일에서 추가하면 공용 주소록으로.
                const scope = detailAccount?.scope === "shared" ? "shared" : "personal";
                const res = await mailApi.createContact({ email: address, name, scope });
                if (res && res.ok === false) {
                    WarningAlert({ message: res.error || "이미 주소록에 있는 메일 주소입니다." });
                } else {
                    SuccessAlert("주소록에 추가했습니다.");
                }
                setContactEmails((prev) => new Set(prev).add(key));
            } catch (error) {
                ErrorAlert({ message: error instanceof Error ? error.message : "주소록에 추가하지 못했습니다." });
            }
        },
        [detailAccount]
    );

    // 헤더 ⚙ = 관리 다이얼로그의 계정 탭 — 다이얼로그 자체는 MailManageHost 가 그린다.
    const handleManageAccounts = useCallback(() => requestMailManage("accounts"), []);

    const handleToggleStar = useCallback(
        (row: MailMessageListItem) => {
            void state.actions.applyMessageAction([row.seq], row.is_starred ? "unstar" : "star");
        },
        [state.actions]
    );

    const handleTrash = useCallback(
        (seq: number) => {
            void state.actions.applyMessageAction([seq], "trash").then(() => state.actions.loadCounts());
        },
        [state.actions]
    );

    // 복수 선택(체크박스) — 폴더/검색이 바뀌면 비운다.
    const [checkedSeqs, setCheckedSeqs] = useState<Set<number>>(() => new Set());
    const toggleChecked = useCallback((seq: number) => {
        setCheckedSeqs((prev) => {
            const next = new Set(prev);
            if (next.has(seq)) next.delete(seq);
            else next.add(seq);
            return next;
        });
    }, []);
    const allChecked = messages.length > 0 && messages.every((row) => checkedSeqs.has(row.seq));
    const someChecked = messages.some((row) => checkedSeqs.has(row.seq));
    const toggleAllChecked = useCallback(() => {
        setCheckedSeqs(allChecked ? new Set() : new Set(messages.map((row) => row.seq)));
    }, [allChecked, messages]);
    useEffect(() => {
        setCheckedSeqs(new Set());
    }, [filterKey]);
    /** 선택 건 일괄 처리(영구 삭제는 확인). */
    const runBulkAction = useCallback(
        (action: BulkMessageAction) => {
            const seqs = messages.filter((row) => checkedSeqs.has(row.seq)).map((row) => row.seq);
            if (seqs.length === 0) return;
            const run = () =>
                void state.actions.applyMessageAction(seqs, action).then((ok: boolean) => {
                    if (!ok) return;
                    setCheckedSeqs(new Set());
                    if (
                        seqs.includes(state.getValue("selectedSeq") as number) &&
                        action !== "read" &&
                        action !== "unread"
                    )
                        state.actions.clearSelection();
                    void state.actions.loadCounts();
                });
            // 확인은 액션 바의 팝퍼가 맡는다.
            run();
        },
        [messages, checkedSeqs, state]
    );
    const checkedRows = messages.filter((row) => checkedSeqs.has(row.seq));
    const checkedCount = checkedRows.length;
    /** 답장/전달 대상 — 체크 1건이면 그 메일, 체크가 없으면 열려 있는 상세. */
    const replyTargetSeq =
        checkedCount === 1
            ? (messages.find((row) => checkedSeqs.has(row.seq))?.seq ?? 0)
            : checkedCount === 0
              ? (detail?.seq ?? 0)
              : 0;
    /** 전달 대상 — 체크된 메일 전부(없으면 열려 있는 상세). */
    const forwardTargetSeqs = checkedCount > 0 ? checkedRows.map((row) => row.seq) : detail ? [detail.seq] : [];
    /** seq 목록으로 답장/전체 답장/전달 작성 창을 연다(상세가 없으면 받아 온다). */
    const composeFromSeqs = useCallback(
        async (seqs: number[], mode: "reply" | "replyAll" | "forward") => {
            if (seqs.length === 0) return;
            if (seqs.length > 20) {
                WarningAlert({ message: "한 번에 전달할 수 있는 메일은 20통까지입니다." });
                return;
            }
            try {
                const details = await Promise.all(
                    seqs.map(async (seq) =>
                        detail && detail.seq === seq
                            ? detail
                            : unwrap(await mailApi.getMessage(seq, false), "메일을 불러오지 못했습니다.")
                    )
                );
                const account = accounts.find((a) => a.seq === details[0].mail_account_seq) ?? defaultAccount;
                if (mode === "replyAll" && details[0].cc.length === 0) {
                    WarningAlert({ message: "참조가 없는 메일은 전체 답장할 수 없습니다. 답장을 사용하세요." });
                    return;
                }
                if (mode === "forward") compose.form.actions.openForwardMany(details, account);
                else compose.form.actions.openFromMessage(details[0], mode, account);
            } catch (error) {
                ErrorAlert({ message: error instanceof Error ? error.message : "메일을 불러오지 못했습니다." });
            }
        },
        [detail, accounts, defaultAccount, compose.form.actions]
    );
    const handleToolbarReply = useCallback(
        (mode: "reply" | "replyAll" | "forward") =>
            composeFromSeqs(mode === "forward" ? forwardTargetSeqs : replyTargetSeq > 0 ? [replyTargetSeq] : [], mode),
        [composeFromSeqs, forwardTargetSeqs, replyTargetSeq]
    );

    // 우클릭 메뉴(데스크탑 표) — 코드샵 지난행사 목록과 같은 Portal 메뉴. 행은 vdt(TableVirtuoso) 의 tr[data-index] 로 찾는다.
    const rowContextMenu = useContextMenu<MailMessageListItem>();
    const handleTableContextMenu = useCallback(
        (event: ReactMouseEvent<HTMLDivElement>) => {
            event.preventDefault();
            const rowEl = (event.target as HTMLElement).closest("tr[data-index]");
            const dataIndex = rowEl?.getAttribute("data-index");
            const row = dataIndex === null || dataIndex === undefined ? undefined : messages[Number(dataIndex)];
            if (!row) {
                rowContextMenu.close();
                return;
            }
            rowContextMenu.openHandler(row)(event);
        },
        [messages, rowContextMenu]
    );
    /**
     * 모바일 카드 길게 누르기 → 팝업 메뉴. 표 우클릭과 같은 메뉴(contextMenuItems)를 손가락 위치에 띄운다.
     * 길게 누르면 브라우저가 contextmenu 를 쏘는데, 그대로 두면 시스템 메뉴·텍스트 선택 핸들이 함께 떠서 막는다.
     * 이어지는 pointer/click 이 카드 onClick(상세 열기)으로 새지 않게 전파도 끊는다(2026-09-13).
     */
    const handleCardContextMenu = useCallback(
        (row: MailMessageListItem, event: ReactMouseEvent) => {
            event.preventDefault();
            event.stopPropagation();
            rowContextMenu.openHandler(row)(event);
        },
        [rowContextMenu]
    );
    const rowAction = useCallback(
        (row: MailMessageListItem, action: BulkMessageAction, move?: MailMoveTarget) =>
            void state.actions.applyMessageAction([row.seq], action, move).then((ok: boolean) => {
                if (!ok) return;
                if (
                    action !== "read" &&
                    action !== "unread" &&
                    action !== "star" &&
                    action !== "unstar" &&
                    detail?.seq === row.seq
                )
                    state.actions.clearSelection();
                void state.actions.loadCounts();
            }),
        [state, detail]
    );
    const isTrashFolder = filters.folder === "trash";
    const isSpamFolder = filters.folder === "spam";
    const isDraftFolder = filters.folder === "draft";
    // 우클릭 메뉴의 스팸 신고/삭제 확인 팝퍼 — 우클릭한 지점을 가상 앵커로 쓴다.
    const [rowConfirm, setRowConfirm] = useState<{
        row: MailMessageListItem;
        kind: "spam" | "trash";
        anchor: { top: number; left: number };
    } | null>(null);
    const rowConfirmAnchor = useMemo(
        () =>
            rowConfirm
                ? {
                      getBoundingClientRect: () =>
                          ({
                              top: rowConfirm.anchor.top,
                              left: rowConfirm.anchor.left,
                              right: rowConfirm.anchor.left,
                              bottom: rowConfirm.anchor.top,
                              width: 0,
                              height: 0,
                              x: rowConfirm.anchor.left,
                              y: rowConfirm.anchor.top,
                              toJSON: () => ({}),
                          }) as DOMRect,
                  }
                : null,
        [rowConfirm]
    );
    /** 이동 대상 목록(우클릭 "이동 ▸" / 툴바 이동) — 사용자 메일함 + 받은편지함/스팸함/휴지통(현재 폴더 제외) */
    const moveTargets = useMemo<MailMoveTargetOption[]>(() => {
        const items: MailMoveTargetOption[] = folders
            .filter((f) => !(filters.folder === "custom" && f.seq === filters.mailFolderSeq))
            .map((f) => ({
                key: `f${f.seq}`,
                label: f.scope === "shared" ? `${f.name} (공용)` : f.name,
                target: { folder: "custom", mail_folder_seq: f.seq },
                folder: f,
            }));
        if (filters.folder !== "inbox") items.push({ key: "inbox", label: "받은편지함", target: { folder: "inbox" } });
        if (filters.folder !== "spam") items.push({ key: "spam", label: "스팸함", target: { folder: "spam" } });
        if (filters.folder !== "trash") items.push({ key: "trash", label: "휴지통", target: { folder: "trash" } });
        return items;
    }, [folders, filters.folder, filters.mailFolderSeq]);
    /** 이 메일을 힌트로 규칙 폼을 연다(우클릭 "규칙 만들기"·상세 ⋮ "규칙 만들기" 공용). */
    const openRuleFromMessage = useCallback((row: MailMessageListItem) => {
        requestMailRuleForm(null, {
                // 조건은 비워 두고, [조건 추가]에서 보낸 사람/제목을 고르면 이 메일의 값이 채워진다
                hints: {
                    from_address: row.from_address ?? "",
                    from_name: row.from_name ?? "",
                    subject: row.subject ?? "",
                    // 받는 사람 = 첫 수신자의 주소("이름 <주소>, …" 요약에서 추출)
                    to: (() => {
                        const first = (row.to_summary ?? "").split(",")[0]?.trim() ?? "";
                        return /<([^>]+)>/.exec(first)?.[1]?.trim() ?? first;
                    })(),
                },
                name: row.from_address ? `${row.from_name || row.from_address} 메일` : "",
                conditions: [],
        });
    }, []);
    const contextMenuItems = useMemo<ContextMenuItem<MailMessageListItem>[]>(
        () => [
            {
                label: "열기",
                icon: <OpenInNewOutlinedIcon fontSize="small" />,
                onClick: (row) => void state.actions.selectMessage(row.seq),
            },
            {
                label: "답장",
                icon: <ReplyArrowIcon fontSize="small" />,
                hidden: isDraftFolder,
                onClick: (row) => void composeFromSeqs([row.seq], "reply"),
            },
            {
                label: "전체 답장",
                icon: <ReplyAllArrowIcon fontSize="small" />,
                // 참조가 없는 메일은 답장과 같으므로 숨긴다
                hidden: (row) => isDraftFolder || !row.has_cc,
                onClick: (row) => void composeFromSeqs([row.seq], "replyAll"),
            },
            {
                label: "전달",
                icon: <ForwardArrowIcon fontSize="small" />,
                hidden: isDraftFolder,
                onClick: (row) => void composeFromSeqs([row.seq], "forward"),
            },
            {
                label: (row) => (row.is_read ? "읽지 않음으로 표시" : "읽음으로 표시"),
                icon: <MarkEmailUnreadOutlinedIcon fontSize="small" />,
                dividerBefore: true,
                hidden: isTrashFolder || isSpamFolder,
                onClick: (row) => rowAction(row, row.is_read ? "unread" : "read"),
            },
            {
                label: (row) => (row.is_starred ? "중요 해제" : "중요 표시"),
                icon: <StarRoundedIcon fontSize="small" />,
                hidden: isTrashFolder || isSpamFolder,
                onClick: (row) => rowAction(row, row.is_starred ? "unstar" : "star"),
            },
            {
                label: "이동",
                icon: <DriveFileMoveOutlinedIcon fontSize="small" />,
                dividerBefore: true,
                hidden: isDraftFolder,
                onClick: () => undefined,
                children: moveTargets.map((t) => ({
                    label: t.label,
                    icon:
                        t.target.folder === "custom" ? (
                            <FolderIcon
                                icon={t.folder?.icon}
                                color={t.folder?.color}
                                shared={t.folder?.scope === "shared"}
                                fontSize={20}
                            />
                        ) : t.target.folder === "spam" ? (
                            <ReportGmailerrorredOutlinedIcon fontSize="small" />
                        ) : t.target.folder === "trash" ? (
                            <TrashIcon fontSize="small" />
                        ) : (
                            <InboxOutlinedIcon fontSize="small" />
                        ),
                    // "이동"으로 스팸함/휴지통에 넣을 땐 확인하지 않는다
                    onClick: (row) => rowAction(row, "move", t.target),
                })),
            },
            {
                label: "규칙 만들기",
                icon: <RuleOutlinedIcon fontSize="small" />,
                hidden: isDraftFolder,
                onClick: (row) => openRuleFromMessage(row),
            },
            {
                label: "스팸 신고",
                icon: <ReportGmailerrorredOutlinedIcon fontSize="small" />,
                dividerBefore: true,
                hidden: filters.folder !== "inbox",
                onClick: (row) =>
                    setRowConfirm({ row, kind: "spam", anchor: rowContextMenu.anchor ?? { top: 0, left: 0 } }),
            },
            {
                label: "스팸 아님",
                icon: <RestoreFromTrashOutlinedIcon fontSize="small" />,
                dividerBefore: true,
                hidden: !isSpamFolder,
                onClick: (row) => rowAction(row, "restore"),
            },
            {
                label: "복원",
                icon: <RestoreFromTrashOutlinedIcon fontSize="small" />,
                dividerBefore: true,
                hidden: !isTrashFolder,
                onClick: (row) => rowAction(row, "restore"),
            },
            {
                label: "삭제",
                icon: <TrashIcon fontSize="small" />,
                dividerBefore: filters.folder !== "inbox" && !isSpamFolder,
                hidden: isTrashFolder,
                onClick: (row) =>
                    setRowConfirm({ row, kind: "trash", anchor: rowContextMenu.anchor ?? { top: 0, left: 0 } }),
            },
            {
                label: "영구 삭제",
                icon: <TrashIcon fontSize="small" />,
                hidden: !isTrashFolder,
                onClick: (row) =>
                    ConfirmDialog({
                        title: "영구 삭제",
                        message: "이 메일을 영구 삭제합니다. 되돌릴 수 없습니다.",
                        onConfirm: () => rowAction(row, "delete"),
                    }),
            },
        ],
        [
            state.actions,
            composeFromSeqs,
            rowAction,
            isDraftFolder,
            isTrashFolder,
            isSpamFolder,
            filters.folder,
            moveTargets,
            rowContextMenu.anchor,
        ]
    );
    // 데스크탑: 항상 보이는 툴바(선택 없으면 비활성) — 헤더 필터 영역. 모바일: 선택 중일 때만 아이콘 바.
    const bulkBar =
        !isMobile || checkedSeqs.size > 0 ? (
            <MailBulkActionBar
                count={checkedCount}
                folder={filters.folder}
                compact={isMobile}
                onAction={runBulkAction}
                replyEnabled={replyTargetSeq > 0 && filters.folder !== "draft"}
                // 상세가 열린 대상은 참조 유무를 바로 알고, 체크만 한 행은 상세를 받은 뒤 검증한다.
                replyAllEnabled={
                    replyTargetSeq > 0 &&
                    filters.folder !== "draft" &&
                    (detail?.seq === replyTargetSeq ? detail.cc.length > 0 : true)
                }
                forwardEnabled={forwardTargetSeqs.length > 0 && filters.folder !== "draft"}
                canMarkRead={checkedRows.some((row) => !row.is_read)}
                canMarkUnread={checkedRows.some((row) => row.is_read)}
                onReply={(mode) => void handleToolbarReply(mode)}
            />
        ) : null;

    // 보기 타입(데스크탑) — 목록형(드로어) / 분할화면(오른쪽 패널). 브라우저별 기억.
    const [viewMode, setViewMode] = useState<MailViewMode>(() => {
        try {
            return window.localStorage.getItem(VIEW_MODE_STORAGE_KEY) === "split" ? "split" : "list";
        } catch {
            return "list";
        }
    });
    // 계정에 저장된 보기 타입을 받아 적용한다(로컬 값은 첫 그림용).
    useEffect(() => {
        if (!logined || isMobile) return;
        let cancelled = false;
        void mailApi
            .getPreferences()
            .then((res) => {
                if (cancelled || !res || res.ok === false) return;
                const mode = res.data?.view_mode === "split" ? "split" : "list";
                setViewMode(mode);
                state.setValue("lastAccountSeq", Number(res.data?.last_account_seq ?? 0) || 0);
                try {
                    window.localStorage.setItem(VIEW_MODE_STORAGE_KEY, mode);
                } catch {
                    // 무시
                }
            })
            .catch(() => undefined);
        return () => {
            cancelled = true;
        };
    }, [logined, isMobile]);
    const handleViewModeChange = useCallback((mode: MailViewMode) => {
        setViewMode(mode);
        try {
            window.localStorage.setItem(VIEW_MODE_STORAGE_KEY, mode);
        } catch {
            // 저장 실패는 무시(세션 동안만 유지)
        }
        // 계정에도 저장(다른 브라우저에서도 같은 보기 타입)
        void mailApi.updatePreferences({ view_mode: mode }).catch(() => undefined);
    }, []);
    const isSplit = !isMobile && viewMode === "split";

    const headerActions = (
        <MailHeaderActions
            accounts={accounts}
            viewMode={isMobile ? undefined : viewMode}
            onViewModeChange={isMobile ? undefined : handleViewModeChange}
            syncing={syncing}
            onSync={() => void state.actions.syncNow(filters.mailAccountSeq).then(() => refreshList())}
            onOpenSettings={handleManageAccounts}
        />
    );

    const headerConfig = useHeaderConfig({
        controller,
        isMobile,
        // 모바일은 헤더가 검색 오버레이라 새 메일은 우하단 FAB, 동기화/설정은 목록 위 툴바가 맡는다.
        left: isMobile ? undefined : (
            <Button
                variant="contained"
                color="primary"
                startIcon={<EditOutlinedIcon />}
                onClick={handleCompose}
                disabled={accounts.length === 0}
            >
                새 메일
            </Button>
        ),
        toolbar: isMobile ? undefined : bulkBar,
        right: isMobile ? undefined : headerActions,
    });

    const columns = useMemo(
        () =>
            getMailColumns(
                handleToggleStar,
                {
                    checked: checkedSeqs,
                    allChecked,
                    someChecked,
                    onToggle: toggleChecked,
                    onToggleAll: toggleAllChecked,
                },
                filters.search,
                // 분할형에서 상세가 열려 목록이 좁아지면 미리보기를 숨겨 제목이 잘 보이게 한다
                !(isSplit && (Boolean(detail) || loadingDetail))
            ),
        [
            handleToggleStar,
            checkedSeqs,
            allChecked,
            someChecked,
            toggleChecked,
            toggleAllChecked,
            filters.search,
            isSplit,
            detail,
            loadingDetail,
        ]
    );
    const hasMore = messages.length < total;

    // 무한 스크롤 — 데스크탑은 vdt onLoadMore, 모바일은 하단 sentinel. 진행 중 중복 호출을 막는다.
    const [loadingMore, setLoadingMore] = useState(false);
    const loadingMoreRef = useRef(false);
    const handleLoadMore = useCallback(() => {
        // 진단 로그(무한 스크롤이 안 이어질 때 원인 확인용) — 호출 자체가 없으면 끝 감지가 안 온 것이다.
        console.log("[mua:loadMore] requested", {
            hasMore,
            loadingList,
            inFlight: loadingMoreRef.current,
        });
        if (!hasMore || loadingList || loadingMoreRef.current) return;
        loadingMoreRef.current = true;
        setLoadingMore(true);
        void state.actions.loadMessages({ append: true, silent: true }).finally(() => {
            loadingMoreRef.current = false;
            setLoadingMore(false);
            console.log("[mua:loadMore] done", {
                messages: (state.getValue("messages") as MailMessageListItem[]).length,
                total: state.getValue("total"),
                page: state.getValue("page"),
            });
        });
    }, [hasMore, loadingList, state]);
    // 데스크탑 폴백 — vdt(react-virtuoso) 의 endReached 가 오지 않는 경우를 대비해 표 스크롤러의 scroll 이벤트로도 감지한다.
    const tableWrapRef = useRef<HTMLDivElement | null>(null);
    useEffect(() => {
        if (isMobile || !hasMore) return;
        const wrap = tableWrapRef.current;
        if (!wrap) return;
        const scroller =
            wrap.querySelector<HTMLElement>('[data-virtuoso-scroller="true"]') ??
            wrap.querySelector<HTMLElement>(".list-layout-left, .overlay-scrollbar-container");
        if (!scroller) {
            console.log("[mua:loadMore] scroller not found (fallback off)");
            return;
        }
        const onScroll = () => {
            const remain = scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight;
            if (remain < 300) handleLoadMore();
        };
        scroller.addEventListener("scroll", onScroll, { passive: true });
        return () => scroller.removeEventListener("scroll", onScroll);
    }, [isMobile, hasMore, handleLoadMore, messages.length]);
    const sentinelRef = useRef<HTMLDivElement | null>(null);
    useEffect(() => {
        const el = sentinelRef.current;
        if (!el || !isMobile || !hasMore) return;
        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0]?.isIntersecting) handleLoadMore();
            },
            { root: findScrollParent(el), rootMargin: "320px" }
        );
        observer.observe(el);
        return () => observer.disconnect();
    }, [isMobile, hasMore, handleLoadMore, messages.length]);

    const detailPanel = (
        <MessageDetailPanel
            detail={detail}
            loading={loadingDetail}
            // 모바일은 mfd 상세 다이얼로그의 ← 가 닫기를 맡고, 본문 스크롤도 다이얼로그가 소유한다.
            embedded={isMobile}
            onClose={() => state.actions.clearSelection()}
            onReply={(mode) => detail && compose.form.actions.openFromMessage(detail, mode, detailAccount)}
            onEditDraft={() => detail && compose.form.actions.openDraft(detail)}
            onComposeTo={handleComposeTo}
            trustedSender={trustedSender}
            onAddContact={canAddContact ? (address, name) => void handleAddContact(address, name) : undefined}
            onToggleStar={() =>
                detail && void state.actions.applyMessageAction([detail.seq], detail.is_starred ? "unstar" : "star")
            }
            onMarkUnread={() =>
                detail &&
                void state.actions.applyMessageAction([detail.seq], "unread").then(() => {
                    state.actions.clearSelection();
                    void state.actions.loadCounts();
                })
            }
            onTrash={() => detail && handleTrash(detail.seq)}
            // ⋮ 메뉴의 이동/규칙 만들기 — 우클릭 메뉴와 같은 대상·프리필을 쓴다.
            moveTargets={moveTargets}
            onMove={(target) => detail && rowAction(detail, "move", target)}
            onCreateRule={() => detail && openRuleFromMessage(detail)}
            // 번역본 보기/원문 보기 전환을 목록 행 제목에 반영한다.
            onTranslationShownChange={(shown, subject) =>
                detail && state.actions.setTranslatedSubject(detail.seq, shown ? subject : null)
            }
            onSpam={() =>
                detail &&
                void state.actions.applyMessageAction([detail.seq], "spam").then(() => state.actions.loadCounts())
            }
            onRestore={() =>
                detail &&
                void state.actions.applyMessageAction([detail.seq], "restore").then(() => state.actions.loadCounts())
            }
            // 확인은 상세 패널의 팝퍼가 맡는다(여기서 ConfirmDialog 를 또 띄우지 않는다).
            onDeleteForever={() =>
                detail &&
                void state.actions.applyMessageAction([detail.seq], "delete").then(() => state.actions.loadCounts())
            }
        />
    );

    const emptyMessage = error
        ? error
        : accounts.length === 0
          ? "등록된 메일 계정이 없습니다. 오른쪽 위 계정 관리에서 계정을 등록하세요."
          : "메일이 없습니다.";

    // 공용 다이얼로그(작성 + 관리 UI) — 데스크탑·모바일 공통.
    // 관리 UI(관리 다이얼로그·계정 폼·규칙 폼)는 앱이 자기 레이아웃에 호스트를 뒀으면(appHostsMailManage) 여기서
    // 그리지 않는다 — 둘 다 그리면 열기 요청을 양쪽이 소비해 두 개가 뜬다.
    const dialogs = (
        <>
            {!appHostsMailManage && <MailManageHost />}
            <ConfirmActionPopper
                open={Boolean(rowConfirm)}
                anchorEl={rowConfirmAnchor}
                placement="bottom-start"
                zIndex={1400}
                title={rowConfirm?.kind === "spam" ? "이 메일을 스팸으로 신고할까요?" : "이 메일을 삭제할까요?"}
                confirmText={rowConfirm?.kind === "spam" ? "스팸 신고" : "삭제"}
                cancelText="취소"
                onCancel={() => setRowConfirm(null)}
                onConfirm={() => {
                    const target = rowConfirm;
                    setRowConfirm(null);
                    if (target) rowAction(target.row, target.kind);
                }}
            />
        </>
    );

    // ── 모바일: 카드 목록 + 상세(mfd 슬라이드) + 새 메일 FAB ─────────────────────────────
    if (isMobile) {
        const scopeAccount = accounts.find((a) => a.seq === filters.mailAccountSeq);
        const scopeLabel = scopeAccount ? scopeAccount.name || scopeAccount.email : "전체 계정";
        const unreadLabel =
            filters.folder === "inbox" && counts.inbox_unread > 0 ? ` · 안 읽음 ${counts.inbox_unread}` : "";
        return (
            <>
                <MobileCardListLayout
                    header={headerConfig}
                    searchOverlayOpen={searchOverlayOpen}
                    storageKey="mail-mobile-list"
                    // 서브페이지 다이얼로그 안에서는 좌우 여백·폭을 다이얼로그가 이미 준다(두 번 들어가지 않게). 페이지 모드는 페이지 여백.
                    inDialog={isEmbedded && !isInline}
                >
                    <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5, minWidth: 0 }}>
                        {/* 툴바 — 현재 계정 범위(+받은편지함 미읽음) · 동기화 · 계정 관리 */}
                        <Box sx={{ display: "flex", alignItems: "center", gap: 1, px: 0.5, minWidth: 0 }}>
                            {bulkBar ? (
                                <Box sx={{ flex: 1, minWidth: 0 }}>{bulkBar}</Box>
                            ) : (
                                <>
                                    <Typography
                                        noWrap
                                        sx={{
                                            flex: 1,
                                            minWidth: 0,
                                            fontSize: mfs(15),
                                            color: "#475569",
                                            fontWeight: 600,
                                        }}
                                    >
                                        {scopeLabel}
                                        {unreadLabel}
                                    </Typography>
                                    {headerActions}
                                </>
                            )}
                        </Box>
                        <MailMobileList
                            rows={messages}
                            loading={loadingList}
                            emptyMessage={emptyMessage}
                            onSelect={(row) => void state.actions.selectMessage(row.seq)}
                            onToggleStar={handleToggleStar}
                            checkedSeqs={checkedSeqs}
                            onToggleCheck={toggleChecked}
                            onRowContextMenu={handleCardContextMenu}
                        />
                        {/* 무한 스크롤 sentinel — 뷰포트(또는 다이얼로그 스크롤러)에 들어오면 다음 페이지 */}
                        {loadingMore ? <MobileListLoadingMoreSpinner /> : null}
                        {hasMore ? <Box ref={sentinelRef} sx={{ height: 1 }} /> : null}
                    </Box>
                </MobileCardListLayout>
                {/* 새 메일 — 업무함 새 업무 FAB 와 같은 자리(우·하단 24). 다이얼로그(portal) 안에서는 하단 바 변수가 0 이라
                    바가 있는 라우트 화면에서만 그 높이만큼 올라간다. 계정이 없으면 계정 등록 창이 열린다(handleCompose). */}
                <Fab
                    color="primary"
                    aria-label="새 메일"
                    onClick={handleCompose}
                    sx={{
                        position: "fixed",
                        right: 24,
                        bottom: "calc(24px + var(--mobile-bottom-nav, 0px))",
                        zIndex: 40,
                    }}
                >
                    <EditIcon />
                </Fab>
                {/* 상세 — 서브페이지 위에 한 겹 더 뜨는 mfd 슬라이드(뒤로가기 한 번에 상세만 닫힌다). */}
                <MobileDetailDialog
                    modalId="mail-message-detail"
                    open={Boolean(detail) || loadingDetail}
                    title={
                        (detail?.folder ?? filters.folder) === "custom"
                            ? (currentUserFolder?.name ?? "메일함")
                            : MAIL_FOLDER_LABELS[(detail?.folder as MailListFolder | undefined) ?? filters.folder]
                    }
                    onClose={() => state.actions.clearSelection()}
                >
                    <Box
                        sx={{
                            bgcolor: "#fff",
                            borderRadius: 2,
                            overflow: "hidden",
                            boxShadow: "0 1px 3px rgba(15,23,42,0.12)",
                        }}
                    >
                        {detailPanel}
                    </Box>
                </MobileDetailDialog>
                {/*
                 * 카드 길게 누르기 메뉴 — 모바일 가지에도 그려야 뜬다(2026-09-13).
                 * 0.3.94 에서 카드에 onContextMenu 를 달았지만 ContextMenu 는 아래 데스크톱 return 에만 있어,
                 * 폰에서는 상태만 열리고 메뉴가 그려지지 않았다(길게 눌러도 아무 일이 없던 원인).
                 */}
                <ContextMenu state={rowContextMenu} items={contextMenuItems} />
                {dialogs}
            </>
        );
    }

    return (
        <Box
            ref={tableWrapRef}
            onContextMenu={handleTableContextMenu}
            sx={{ userSelect: "none", height: "100%", minHeight: 0 }}
        >
            <ContextMenu state={rowContextMenu} items={contextMenuItems} />
            <ListLayout
                storageKey="mail-list-layout"
                header={headerConfig}
                tableProps={{
                    columns,
                    data: messages,
                    totalCount: total,
                    getRowId: (row: MailMessageListItem) => row.seq,
                    rowHeight: 44,
                    loading: loadingList,
                    selectedRowId: selectedSeq || null,
                    selectedRowSx: { backgroundColor: "#dbeafe", boxShadow: "inset 3px 0 0 #3b82f6" },
                    onRowClick: (row: MailMessageListItem) => void state.actions.selectMessage(row.seq),
                    emptyMessage,
                    // 스크롤이 끝에 가까워지면 다음 페이지를 이어 붙인다(더 보기 버튼 없음).
                    onLoadMore: hasMore
                        ? () => {
                              console.log("[mua:loadMore] vdt onLoadMore");
                              handleLoadMore();
                          }
                        : undefined,
                }}
                onEscape={() => state.actions.clearSelection()}
                rightConfig={
                    isSplit ? { visible: Boolean(detail) || loadingDetail, ratio: 0.5, minWidth: 420 } : undefined
                }
                rightPanel={isSplit ? detailPanel : undefined}
            />
            {/* 목록형: 상세는 오른쪽 드로어(목록을 분할하지 않는다). 닫기 = X · Esc · 바깥 클릭. */}
            <Drawer
                anchor="right"
                open={!isSplit && (Boolean(detail) || loadingDetail)}
                onClose={() => state.actions.clearSelection()}
                slotProps={{
                    paper: {
                        sx: { width: "min(850px, 50vw)", maxWidth: "50vw", display: "flex", flexDirection: "column" },
                    },
                }}
            >
                {detailPanel}
            </Drawer>
            {dialogs}
        </Box>
    );
}
